import{_ as o,r as a,o as l,c as p,e as s,a as i,s as r}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"Relations - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Configuring the Relation Behavior","slug":"configuring-the-relation-behavior","link":"#configuring-the-relation-behavior","children":[{"level":3,"title":"Custom Messages","slug":"custom-messages","link":"#custom-messages","children":[]}]},{"level":2,"title":"Relationship Types","slug":"relationship-types","link":"#relationship-types","children":[{"level":3,"title":"Has Many","slug":"has-many","link":"#has-many","children":[]},{"level":3,"title":"Belongs to Many","slug":"belongs-to-many","link":"#belongs-to-many","children":[]},{"level":3,"title":"Belongs to Many (with Pivot Data)","slug":"belongs-to-many-with-pivot-data","link":"#belongs-to-many-with-pivot-data","children":[]},{"level":3,"title":"Belongs To","slug":"belongs-to","link":"#belongs-to","children":[]},{"level":3,"title":"Has One","slug":"has-one","link":"#has-one","children":[]}]},{"level":2,"title":"Displaying a Relation Manager","slug":"displaying-a-relation-manager","link":"#displaying-a-relation-manager","children":[]},{"level":2,"title":"Extending Relation Behavior","slug":"extending-relation-behavior","link":"#extending-relation-behavior","children":[{"level":3,"title":"Extending Relation Configuration","slug":"extending-relation-configuration","link":"#extending-relation-configuration","children":[]},{"level":3,"title":"Extending the View Widget","slug":"extending-the-view-widget","link":"#extending-the-view-widget","children":[{"level":4,"title":"How to Remove a Column","slug":"how-to-remove-a-column","link":"#how-to-remove-a-column","children":[]}]},{"level":3,"title":"Extending the Manage Widget","slug":"extending-the-manage-widget","link":"#extending-the-manage-widget","children":[]},{"level":3,"title":"Extending the Pivot Widget","slug":"extending-the-pivot-widget","link":"#extending-the-pivot-widget","children":[]},{"level":3,"title":"Extending the Filter Widgets","slug":"extending-the-filter-widgets","link":"#extending-the-filter-widgets","children":[]},{"level":3,"title":"Extending the Refresh Results","slug":"extending-the-refresh-results","link":"#extending-the-refresh-results","children":[]}]}],"relativePath":"2.x/backend/relations.md","filePath":"2.x/backend/relations.md"}'),c={name:"2.x/backend/relations.md"};function d(u,n,k,g,m,h){const e=a("pre-heading"),t=a("post-heading");return l(),p("div",null,[s(e),n[0]||(n[0]=i("h1",null,"Relations",-1)),s(t),n[1]||(n[1]=r(`<p><strong>Relation Behavior</strong> is a controller modifier used for easily managing complex <a href="./../database/model.html">model</a> relationships on a page. Not to be confused with <a href="./lists.html#oc-available-column-types">List relation columns</a> or <a href="./forms.html#widget-relation">Form relation fields</a> that only provide simple management.</p><p>Relation behavior depends on <a href="#oc-relationship-types">relation definitions</a>. In order to use the relation behavior you should add the <code>Backend\\Behaviors\\RelationController</code> definition to the <code>$implement</code> field of the controller class. Also, the <code>$relationConfig</code> class property should be defined and its value should refer to the YAML file used for <a href="#oc-configuring-the-relation-behavior">configuring the behavior options</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Projects<span class="token punctuation">\\</span>Controllers</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Projects</span> <span class="token keyword">extends</span> <span class="token class-name">Controller</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$implement</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>FormController</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>RelationController</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$formConfig</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;config_form.yaml&#39;</span><span class="token punctuation">;</span>
    <span class="token keyword">public</span> <span class="token variable">$relationConfig</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;config_relation.yaml&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><blockquote><p><strong>Note</strong>: Very often the relation behavior is used together with the <a href="./forms.html">form behavior</a>.</p></blockquote><p><a id="oc-configuring-the-relation-behavior"></a></p><h2 id="configuring-the-relation-behavior"><a href="#configuring-the-relation-behavior" class="header-anchor">#</a> Configuring the Relation Behavior</h2><p>The configuration file referred in the <code>$relationConfig</code> property is defined in YAML format. The file should be placed into the controller&#39;s <a href="./controllers-ajax.html">views directory</a>. The required configuration depends on the <a href="#oc-relationship-types">relationship type</a> between the target model and the related model.</p><p>The first level field in the relation configuration file defines the relationship name in the target model. For example:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Invoice</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$hasMany</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;items&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Pay<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>InvoiceItem</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>An <em>Invoice</em> model with a relationship called <code>items</code> should define the first level field using the same relationship name:</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># ===================================</span>
<span class="token comment">#  Relation Behavior Config</span>
<span class="token comment"># ===================================</span>

<span class="token key atrule">items</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Invoice Line Item
    <span class="token key atrule">view</span><span class="token punctuation">:</span>
        <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/pay/models/invoiceitem/columns.yaml
        <span class="token key atrule">toolbarButtons</span><span class="token punctuation">:</span> create<span class="token punctuation">|</span>delete
    <span class="token key atrule">manage</span><span class="token punctuation">:</span>
        <span class="token key atrule">form</span><span class="token punctuation">:</span> $/acme/pay/models/invoiceitem/fields.yaml
        <span class="token key atrule">recordsPerPage</span><span class="token punctuation">:</span> <span class="token number">10</span>
</code></pre></div><p>The following options are then used for each relationship name definition:</p><div class="table"><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>a label for the relation, in the singular tense, required.</td></tr><tr><td><strong>view</strong></td><td>configuration specific to the view container, see below.</td></tr><tr><td><strong>manage</strong></td><td>configuration specific to the management popup, see below.</td></tr><tr><td><strong>pivot</strong></td><td>a reference to form field definition file, used for <a href="#oc-belongs-to-many-with-pivot-data">relations with pivot table data</a>.</td></tr><tr><td><strong>emptyMessage</strong></td><td>a message to display when the relationship is empty, optional.</td></tr><tr><td><strong>readOnly</strong></td><td>disables the ability to add, update, delete or create relations. default: false</td></tr><tr><td><strong>deferredBinding</strong></td><td><a href="./../database/relations.html#oc-deferred-binding">defers all binding actions using a session key</a> when it is available. default: false</td></tr></tbody></table></div><p>These configuration values can be specified for the <strong>view</strong> or <strong>manage</strong> options, where applicable to the render type of list, form or both.</p><div class="table"><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><strong>form</strong></td><td>Form</td><td>a reference to form field definition file, see <a href="./forms.html#oc-defining-form-fields">backend form fields</a>.</td></tr><tr><td><strong>list</strong></td><td>List</td><td>a reference to list column definition file, see <a href="./lists.html#oc-defining-list-columns">backend list columns</a>.</td></tr><tr><td><strong>showFlash</strong></td><td>Both</td><td>enables the display of flash messages after a successful action. Default: true</td></tr><tr><td><strong>showSearch</strong></td><td>List</td><td>display an input for searching the records. Default: false</td></tr><tr><td><strong>showSorting</strong></td><td>List</td><td>displays the sorting link on each column. Default: true</td></tr><tr><td><strong>defaultSort</strong></td><td>List</td><td>sets a default sorting column and direction when user preference is not defined. Supports a string or an array with keys <code>column</code> and <code>direction</code>.</td></tr><tr><td><strong>recordsPerPage</strong></td><td>List</td><td>maximum rows to display for each page.</td></tr><tr><td><strong>noRecordsMessage</strong></td><td>List</td><td>a message to display when no records are found, can refer to a <a href="./../plugin/localization.html">localization string</a>.</td></tr><tr><td><strong>conditions</strong></td><td>List</td><td>specifies a raw where query statement to apply to the list model query.</td></tr><tr><td><strong>scope</strong></td><td>List</td><td>specifies a <a href="./../database/model.html#oc-query-scopes">query scope method</a> defined in the <em>related form model</em> to apply to the list query always. The model that this relationship will be attached to (i.e. the parent model) is passed to this scope method as the second parameter (<code>$query</code> is the first).</td></tr><tr><td><strong>searchMode</strong></td><td>List</td><td>defines the search strategy to either contain all words, any word or exact phrase. Supported options: all, any, exact. Default: all.</td></tr><tr><td><strong>searchScope</strong></td><td>List</td><td>specifies a <a href="./../database/model.html#oc-query-scopes">query scope method</a> defined in the <strong>related form model</strong> to apply to the search query, the first argument will contain the search term.</td></tr><tr><td><strong>filter</strong></td><td>List</td><td>a reference to a filter scopes definition file, see <a href="./lists.html#oc-using-list-filters">backend list filters</a>.</td></tr></tbody></table></div><p>These configuration values can be specified only for the <strong>view</strong> options.</p><div class="table"><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><strong>showCheckboxes</strong></td><td>List</td><td>displays checkboxes next to each record.</td></tr><tr><td><strong>recordUrl</strong></td><td>List</td><td>link each list record to another page. Eg: <strong>users/update/:id</strong>. The <code>:id</code> part is replaced with the record identifier.</td></tr><tr><td><strong>customViewPath</strong></td><td>List</td><td>specify a custom view path to override partials used by the list.</td></tr><tr><td><strong>recordOnClick</strong></td><td>List</td><td>custom JavaScript code to execute when clicking on a record.</td></tr><tr><td><strong>toolbarPartial</strong></td><td>Both</td><td>a reference to a controller partial file with the toolbar buttons. Eg: <strong>_relation_toolbar.htm</strong>. This option overrides the <em>toolbarButtons</em> option.</td></tr><tr><td><strong>toolbarButtons</strong></td><td>Both</td><td>the set of buttons to display. This can be formatted as an array or a pipe separated string, or set to <code>false</code> to show no buttons. Available options are: <code>create</code>, <code>update</code>, <code>delete</code>, <code>add</code>, <code>remove</code>, <code>link</code>, &amp; <code>unlink</code>. Example: \`add</td></tr><tr><td><strong>structure</strong></td><td>List</td><td>options to enable <a href="./../backend/reorder.html">sorting records</a> for the list.</td></tr></tbody></table></div><p>These configuration values can be specified only for the <strong>manage</strong> options.</p><div class="table"><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><strong>title</strong></td><td>Both</td><td>a popup title, can refer to a <a href="./../plugin/localization.html">localization string</a>.</td></tr><tr><td><strong>context</strong></td><td>Form</td><td>context of the form being displayed. Can be a string or an array with keys: create, update.</td></tr></tbody></table></div><h3 id="custom-messages"><a href="#custom-messages" class="header-anchor">#</a> Custom Messages</h3><p>Specify the <code>customMessages</code> option to override the default messages used by the Relation Controller. The values can be plain text or can refer to a <a href="./../plugin/localization.html">localization string</a>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">customMessages</span><span class="token punctuation">:</span>
    <span class="token key atrule">buttonCreate</span><span class="token punctuation">:</span> Make Thing
    <span class="token key atrule">buttonDelete</span><span class="token punctuation">:</span> Destroy Thing
</code></pre></div><p>You may also modify messages in the context of the related field being displayed. The following will override the <code>createButton</code> message for the <code>items</code> relation only.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">items</span><span class="token punctuation">:</span>
    <span class="token key atrule">customMessages</span><span class="token punctuation">:</span>
        <span class="token key atrule">buttonCreate</span><span class="token punctuation">:</span> New Item<span class="token tag">!</span>
</code></pre></div><p>The following messages are available to override as custom messages.</p><div class="table"><table tabindex="0"><thead><tr><th>Message</th><th>Default Message</th></tr></thead><tbody><tr><td>buttonCreate</td><td>Create :name</td></tr><tr><td>buttonUpdate</td><td>Update :name</td></tr><tr><td>buttonAdd</td><td>Add :name</td></tr><tr><td>buttonLink</td><td>Link :name</td></tr><tr><td>buttonDelete</td><td>Delete</td></tr><tr><td>buttonRemove</td><td>Remove</td></tr><tr><td>buttonUnlink</td><td>Unlink</td></tr><tr><td>confirmDelete</td><td>Are you sure?</td></tr><tr><td>confirmUnlink</td><td>Are you sure?</td></tr><tr><td>titlePreviewForm</td><td>Preview :name</td></tr><tr><td>titleCreateForm</td><td>Create :name</td></tr><tr><td>titleUpdateForm</td><td>Update :name</td></tr><tr><td>titleLinkForm</td><td>Link a New :name</td></tr><tr><td>titleAddForm</td><td>Add a New :name</td></tr><tr><td>titlePivotForm</td><td>Related :name Data</td></tr><tr><td>flashCreate</td><td>:name Created</td></tr><tr><td>flashUpdate</td><td>:name Updated</td></tr><tr><td>flashDelete</td><td>:name Deleted</td></tr><tr><td>flashAdd</td><td>:name Added</td></tr><tr><td>flashLink</td><td>:name Linked</td></tr><tr><td>flashRemove</td><td>:name Removed</td></tr><tr><td>flashUnlink</td><td>:name Unlinked</td></tr></tbody></table></div><p><a id="oc-relationship-types"></a></p><h2 id="relationship-types"><a href="#relationship-types" class="header-anchor">#</a> Relationship Types</h2><p>How the relation manager is displayed depends on the relationship definition in the target model. The relationship type will also determine the configuration requirements, these are shown in <strong>bold</strong>. The following relationship types are available:</p><h3 id="has-many"><a href="#has-many" class="header-anchor">#</a> Has Many</h3><ol><li>Related records are displayed as a list (<strong>view.list</strong>).</li><li>Clicking a record will display an update form (<strong>manage.form</strong>).</li><li>Clicking <em>Add</em> will display a selection list (<strong>manage.list</strong>).</li><li>Clicking <em>Create</em> will display a create form (<strong>manage.form</strong>).</li><li>Clicking <em>Delete</em> will destroy the record(s).</li><li>Clicking <em>Remove</em> will orphan the relationship.</li></ol><p>For example, if a <em>Blog Post</em> has many <em>Comments</em>, the target model is set as the blog post and a list of comments is displayed, using columns from the <strong>list</strong> definition. Clicking on a comment opens a popup form with the fields defined in <strong>form</strong> to update the comment. Comments can be created in the same way. Below is an example of the relation behavior configuration file:</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># ===================================</span>
<span class="token comment">#  Relation Behavior Config</span>
<span class="token comment"># ===================================</span>

<span class="token key atrule">comments</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Comment
    <span class="token key atrule">manage</span><span class="token punctuation">:</span>
        <span class="token key atrule">form</span><span class="token punctuation">:</span> $/acme/blog/models/comment/fields.yaml
        <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/blog/models/comment/columns.yaml
    <span class="token key atrule">view</span><span class="token punctuation">:</span>
        <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/blog/models/comment/columns.yaml
        <span class="token key atrule">toolbarButtons</span><span class="token punctuation">:</span> create<span class="token punctuation">|</span>delete
</code></pre></div><h3 id="belongs-to-many"><a href="#belongs-to-many" class="header-anchor">#</a> Belongs to Many</h3><ol><li>Related records are displayed as a list (<strong>view.list</strong>).</li><li>Clicking <em>Add</em> will display a selection list (<strong>manage.list</strong>).</li><li>Clicking <em>Create</em> will display a create form (<strong>manage.form</strong>).</li><li>Clicking <em>Delete</em> will destroy the pivot table record(s).</li><li>Clicking <em>Remove</em> will orphan the relationship.</li></ol><p>For example, if a <em>User</em> belongs to many <em>Roles</em>, the target model is set as the user and a list of roles is displayed, using columns from the <strong>list</strong> definition. Existing roles can be added and removed from the user. Below is an example of the relation behavior configuration file:</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># ===================================</span>
<span class="token comment">#  Relation Behavior Config</span>
<span class="token comment"># ===================================</span>

<span class="token key atrule">roles</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Role
    <span class="token key atrule">view</span><span class="token punctuation">:</span>
        <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/user/models/role/columns.yaml
        <span class="token key atrule">toolbarButtons</span><span class="token punctuation">:</span> add<span class="token punctuation">|</span>remove
    <span class="token key atrule">manage</span><span class="token punctuation">:</span>
        <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/user/models/role/columns.yaml
        <span class="token key atrule">form</span><span class="token punctuation">:</span> $/acme/user/models/role/fields.yaml
</code></pre></div><p><a id="oc-belongs-to-many-with-pivot-data"></a></p><h3 id="belongs-to-many-with-pivot-data"><a href="#belongs-to-many-with-pivot-data" class="header-anchor">#</a> Belongs to Many (with Pivot Data)</h3><blockquote><p><strong>Note</strong>: Pivot data is not supported by <a href="./../database/relations.html#oc-deferred-binding">deferred bindings</a> at this time, so the parent model should exist. If your relation behavior config has <code>deferredBinding: true</code>, the pivot data will <strong>not</strong> be available to use in the list configuration (ex.<code>pivot[attribute]</code>).</p></blockquote><ol><li>Related records are displayed as a list (<strong>view.list</strong>).</li><li>Clicking a record will display an update form (<strong>pivot.form</strong>).</li><li>Clicking <em>Add</em> will display a selection list (<strong>manage.list</strong>), then a data entry form (<strong>pivot.form</strong>).</li><li>Clicking <em>Remove</em> will destroy the pivot table record(s).</li></ol><p>Continuing the example in <em>Belongs To Many</em> relations, if a role also carried an expiry date, clicking on a role will open a popup form with the fields defined in <strong>pivot</strong> to update the expiry date. Below is an example of the relation behavior configuration file:</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># ===================================</span>
<span class="token comment">#  Relation Behavior Config</span>
<span class="token comment"># ===================================</span>

<span class="token key atrule">roles</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Role
    <span class="token key atrule">view</span><span class="token punctuation">:</span>
        <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/user/models/role/columns.yaml
    <span class="token key atrule">manage</span><span class="token punctuation">:</span>
        <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/user/models/role/columns.yaml
    <span class="token key atrule">pivot</span><span class="token punctuation">:</span>
        <span class="token key atrule">form</span><span class="token punctuation">:</span> $/acme/user/models/role/fields.yaml
</code></pre></div><p>Pivot data is available when defining form fields and list columns via the <code>pivot</code> relation, see the example below:</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># ===================================</span>
<span class="token comment">#  Relation Behavior Config</span>
<span class="token comment"># ===================================</span>

<span class="token key atrule">teams</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Team
    <span class="token key atrule">view</span><span class="token punctuation">:</span>
        <span class="token key atrule">list</span><span class="token punctuation">:</span>
            <span class="token key atrule">columns</span><span class="token punctuation">:</span>
                <span class="token key atrule">name</span><span class="token punctuation">:</span>
                    <span class="token key atrule">label</span><span class="token punctuation">:</span> Name
                pivot<span class="token punctuation">[</span>team_color<span class="token punctuation">]</span><span class="token punctuation">:</span>
                    <span class="token key atrule">label</span><span class="token punctuation">:</span> Team color
    <span class="token key atrule">manage</span><span class="token punctuation">:</span>
        <span class="token key atrule">list</span><span class="token punctuation">:</span>
            <span class="token key atrule">columns</span><span class="token punctuation">:</span>
                <span class="token key atrule">name</span><span class="token punctuation">:</span>
                    <span class="token key atrule">label</span><span class="token punctuation">:</span> Name
    <span class="token key atrule">pivot</span><span class="token punctuation">:</span>
        <span class="token key atrule">form</span><span class="token punctuation">:</span>
            <span class="token key atrule">fields</span><span class="token punctuation">:</span>
                pivot<span class="token punctuation">[</span>team_color<span class="token punctuation">]</span><span class="token punctuation">:</span>
                    <span class="token key atrule">label</span><span class="token punctuation">:</span> Team color
</code></pre></div><h3 id="belongs-to"><a href="#belongs-to" class="header-anchor">#</a> Belongs To</h3><ol><li>Related record is displayed as a preview form (<strong>view.form</strong>).</li><li>Clicking <em>Create</em> will display a create form (<strong>manage.form</strong>).</li><li>Clicking <em>Update</em> will display an update form (<strong>manage.form</strong>).</li><li>Clicking <em>Link</em> will display a selection list (<strong>manage.list</strong>).</li><li>Clicking <em>Unlink</em> will orphan the relationship.</li><li>Clicking <em>Delete</em> will destroy the record.</li></ol><p>For example, if a <em>Phone</em> belongs to a <em>Person</em> the relation manager will display a form with the fields defined in <strong>form</strong>. Clicking the Link button will display a list of People to associate with the Phone. Clicking the Unlink button will dissociate the Phone with the Person.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># ===================================</span>
<span class="token comment">#  Relation Behavior Config</span>
<span class="token comment"># ===================================</span>

<span class="token key atrule">person</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Person
    <span class="token key atrule">view</span><span class="token punctuation">:</span>
        <span class="token key atrule">form</span><span class="token punctuation">:</span> $/acme/user/models/person/fields.yaml
        <span class="token key atrule">toolbarButtons</span><span class="token punctuation">:</span> link<span class="token punctuation">|</span>unlink
    <span class="token key atrule">manage</span><span class="token punctuation">:</span>
        <span class="token key atrule">form</span><span class="token punctuation">:</span> $/acme/user/models/person/fields.yaml
        <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/user/models/person/columns.yaml
</code></pre></div><h3 id="has-one"><a href="#has-one" class="header-anchor">#</a> Has One</h3><ol><li>Related record is displayed as a preview form (<strong>view.form</strong>).</li><li>Clicking <em>Create</em> will display a create form (<strong>manage.form</strong>).</li><li>Clicking <em>Update</em> will display an update form (<strong>manage.form</strong>).</li><li>Clicking <em>Link</em> will display a selection list (<strong>manage.list</strong>).</li><li>Clicking <em>Unlink</em> will orphan the relationship.</li><li>Clicking <em>Delete</em> will destroy the record.</li></ol><p>For example, if a <em>Person</em> has one <em>Phone</em> the relation manager will display form with the fields defined in <strong>form</strong> for the Phone. When clicking the Update button, a popup is displayed with the fields now editable. If the Person already has a Phone the fields are update, otherwise a new Phone is created for them.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># ===================================</span>
<span class="token comment">#  Relation Behavior Config</span>
<span class="token comment"># ===================================</span>

<span class="token key atrule">phone</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Phone
    <span class="token key atrule">view</span><span class="token punctuation">:</span>
        <span class="token key atrule">form</span><span class="token punctuation">:</span> $/acme/user/models/phone/fields.yaml
        <span class="token key atrule">toolbarButtons</span><span class="token punctuation">:</span> update<span class="token punctuation">|</span>delete
    <span class="token key atrule">manage</span><span class="token punctuation">:</span>
        <span class="token key atrule">form</span><span class="token punctuation">:</span> $/acme/user/models/phone/fields.yaml
        <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/user/models/phone/columns.yaml
</code></pre></div><h2 id="displaying-a-relation-manager"><a href="#displaying-a-relation-manager" class="header-anchor">#</a> Displaying a Relation Manager</h2><p>Before relations can be managed on any page, the target model must first be initialized in the controller by calling the <code>initRelation</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$post</span> <span class="token operator">=</span> <span class="token class-name static-context">Post</span><span class="token operator">::</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">,</span> <span class="token number">7</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">first</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">initRelation</span><span class="token punctuation">(</span><span class="token variable">$post</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><blockquote><p><strong>Note</strong>: The <a href="./forms.html">form behavior</a> will automatically initialize the model on its create, update and preview actions.</p></blockquote><p>The relation manager can then be displayed for a specified relation definition by calling the <code>relationRender</code> method. For example, if you want to display the relation manager on the <a href="./forms.html#oc-preview-view">Preview</a> page, the <strong>preview.htm</strong> view contents could look like this:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">formRenderPreview</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>

<span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">relationRender</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;comments&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><p>You may instruct the relation manager to render in read only mode by passing the option as the second argument:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">relationRender</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;comments&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;readOnly&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><h2 id="extending-relation-behavior"><a href="#extending-relation-behavior" class="header-anchor">#</a> Extending Relation Behavior</h2><p>Sometimes you may wish to modify the default relation behavior and there are several ways you can do this.</p><h3 id="extending-relation-configuration"><a href="#extending-relation-configuration" class="header-anchor">#</a> Extending Relation Configuration</h3><p>Provides an opportunity to manipulate the relation configuration. The following example can be used to inject a different columns.yaml file based on a property of your model.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">relationExtendConfig</span><span class="token punctuation">(</span><span class="token variable">$config</span><span class="token punctuation">,</span> <span class="token variable">$field</span><span class="token punctuation">,</span> <span class="token variable">$model</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// Make sure the model and field matches those you want to manipulate</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token variable">$model</span> <span class="token keyword">instanceof</span> <span class="token class-name">MyModel</span> <span class="token operator">||</span> <span class="token variable">$field</span> <span class="token operator">!=</span> <span class="token string single-quoted-string">&#39;myField&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">// Show a different list for business customers</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">mode</span> <span class="token operator">==</span> <span class="token string single-quoted-string">&#39;b2b&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$config</span><span class="token operator">-&gt;</span><span class="token property">view</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;list&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;$/author/plugin_name/models/mymodel/b2b_columns.yaml&#39;</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="extending-the-view-widget"><a href="#extending-the-view-widget" class="header-anchor">#</a> Extending the View Widget</h3><p>Provides an opportunity to manipulate the view widget. For example you might want to toggle showCheckboxes based on a property of your model.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">relationExtendViewWidget</span><span class="token punctuation">(</span><span class="token variable">$widget</span><span class="token punctuation">,</span> <span class="token variable">$field</span><span class="token punctuation">,</span> <span class="token variable">$model</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// Make sure the model and field matches those you want to manipulate</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token variable">$model</span> <span class="token keyword">instanceof</span> <span class="token class-name">MyModel</span> <span class="token operator">||</span> <span class="token variable">$field</span> <span class="token operator">!=</span> <span class="token string single-quoted-string">&#39;myField&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">constant</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$widget</span><span class="token operator">-&gt;</span><span class="token property">showCheckboxes</span> <span class="token operator">=</span> <span class="token constant boolean">false</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="how-to-remove-a-column"><a href="#how-to-remove-a-column" class="header-anchor">#</a> How to Remove a Column</h4><p>Since the widget has not completed initializing at this point of the runtime cycle you can&#39;t call <code>$widget-&gt;removeColumn()</code>. The <code>addColumns()</code> method as described in the <a href="./../backend/lists.html#oc-extending-column-definitions">ListController documentation</a> will work as expected, but to remove a column we need to listen to the &#39;list.extendColumns&#39; event within the <code>relationExtendViewWidget()</code> method. The following example shows how to remove a column.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">relationExtendViewWidget</span><span class="token punctuation">(</span><span class="token variable">$widget</span><span class="token punctuation">,</span> <span class="token variable">$field</span><span class="token punctuation">,</span> <span class="token variable">$model</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// Make sure the model and field matches those you want to manipulate</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token variable">$model</span> <span class="token keyword">instanceof</span> <span class="token class-name">MyModel</span> <span class="token operator">||</span> <span class="token variable">$field</span> <span class="token operator">!=</span> <span class="token string single-quoted-string">&#39;myField&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">// This will work</span>
    <span class="token variable">$widget</span><span class="token operator">-&gt;</span><span class="token function">bindEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;list.extendColumns&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$widget</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$widget</span><span class="token operator">-&gt;</span><span class="token function">removeColumn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;my_column&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="extending-the-manage-widget"><a href="#extending-the-manage-widget" class="header-anchor">#</a> Extending the Manage Widget</h3><p>Provides an opportunity to manipulate the manage widget of your relation.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">relationExtendManageWidget</span><span class="token punctuation">(</span><span class="token variable">$widget</span><span class="token punctuation">,</span> <span class="token variable">$field</span><span class="token punctuation">,</span> <span class="token variable">$model</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// Make sure the field is the expected one</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$field</span> <span class="token operator">!=</span> <span class="token string single-quoted-string">&#39;myField&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">// Manipulate widget as needed</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="extending-the-pivot-widget"><a href="#extending-the-pivot-widget" class="header-anchor">#</a> Extending the Pivot Widget</h3><p>Provides an opportunity to manipulate the pivot widget of your relation.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">relationExtendPivotWidget</span><span class="token punctuation">(</span><span class="token variable">$widget</span><span class="token punctuation">,</span> <span class="token variable">$field</span><span class="token punctuation">,</span> <span class="token variable">$model</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// Make sure the field is the expected one</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$field</span> <span class="token operator">!=</span> <span class="token string single-quoted-string">&#39;myField&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">// Manipulate widget as needed</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="extending-the-filter-widgets"><a href="#extending-the-filter-widgets" class="header-anchor">#</a> Extending the Filter Widgets</h3><p>There are two filter widgets that may be extended using the following methods, one for the view mode and one for the manage mode of the <code>RelationController</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">relationExtendViewFilterWidget</span><span class="token punctuation">(</span><span class="token variable">$widget</span><span class="token punctuation">,</span> <span class="token variable">$field</span><span class="token punctuation">,</span> <span class="token variable">$model</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// Extends the view filter widget</span>
<span class="token punctuation">}</span>

<span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">relationExtendManageFilterWidget</span><span class="token punctuation">(</span><span class="token variable">$widget</span><span class="token punctuation">,</span> <span class="token variable">$field</span><span class="token punctuation">,</span> <span class="token variable">$model</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// Extends the manage filter widget</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Examples on how to add or remove scopes programmatically in the filter widgets can be found in the <strong>Extending filter scopes</strong> section of the <a href="./../backend/lists.html#oc-extending-filter-scopes">Backend list documentation</a>.</p><h3 id="extending-the-refresh-results"><a href="#extending-the-refresh-results" class="header-anchor">#</a> Extending the Refresh Results</h3><p>The view widget is often refreshed when the manage widget makes a change, you can use this method to inject additional containers when this process occurs. Return an array with the extra values to send to the browser, eg:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">relationExtendRefreshResults</span><span class="token punctuation">(</span><span class="token variable">$field</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// Make sure the field is the expected one</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$field</span> <span class="token operator">!=</span> <span class="token string single-quoted-string">&#39;myField&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;#myCounter&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Total records: 6&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div>`,85))])}const v=o(c,[["render",d]]);export{y as __pageData,v as default};
